package dev.zomboid.firstaid;
public final class RevivalHud {
 public static void render(Object graphics){try{Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance"),p=R.get(mc,"player");if(p==null)return;Object m=R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"getDamageModel",p);if(m==null||!Revival.active(m))return;Object font=R.get(mc,"font");int w=((Number)R.call(graphics,"guiWidth")).intValue();int y=12;int ticks=((Number)R.call(m,"getUnconsciousTicks")).intValue();String reason=R.call(m,"getUnconsciousReasonKey").toString();String chance=reason.startsWith("firstaid.gui.downed_")?reason.substring(reason.lastIndexOf('_')+1):"25";Object key=R.get(R.type("ichttt.mods.firstaid.client.ClientHooks"),"GIVE_UP");String binding=R.call(R.call(key,"getTranslatedKeyMessage"),"getString").toString();R.call(graphics,"fill",w/2-145,y,w/2+145,y+66,0xDB151B17);R.call(graphics,"drawCenteredString",font,"DERRIBADO · PUEDEN REANIMARTE",w/2,y+6,0xFFE2C778);R.call(graphics,"drawCenteredString",font,"Tiempo restante: "+Math.max(0,ticks/20)+" s",w/2,y+19,0xFFFFFFFF);R.call(graphics,"drawCenteredString",font,ticks>2200?"Recuperación automática en "+((ticks-2200+19)/20)+" s · "+chance+"%":"Auto-reanimación fallida · necesitas asistencia",w/2,y+32,0xFFBCCCB7);R.call(graphics,"fill",w/2-130,y+46,w/2+130,y+52,0xFF303C32);R.call(graphics,"fill",w/2-130,y+46,w/2-130+260*Math.max(0,Math.min(2400,ticks))/2400,y+52,0xFFC6AC6A);R.call(graphics,"drawCenteredString",font,"Pide ayuda · Mantén "+binding+" 3 s: rendirse",w/2,y+56,0xFFB8B8B8);}catch(Exception e){}}
}
